// ---------------------------------------------------------------------------
// Output interface — defines the contract for any IO sink.
// The default implementation writes to process.stdout/stderr.
// Swap it out in tests or to redirect to a file.
// ---------------------------------------------------------------------------

export interface CliOutput {
  out(msg: string): void;
  err(msg: string): void;
}

// Default output using process.stdout/stderr
let impl: CliOutput = {
  out: (msg) => process.stdout.write(msg),
  err: (msg) => process.stderr.write(msg),
};

export function setOutput(newImpl: CliOutput): void {
  impl = newImpl;
}

export function resetOutput(): void {
  impl = {
    out: (msg) => process.stdout.write(msg),
    err: (msg) => process.stderr.write(msg),
  };
}

// Emit a raw string to stdout.
export function output(message: string): void {
  impl.out(message);
}

// Emit a single line to stdout with trailing newline.
export function outputLine(message: string): void {
  impl.out(message + "\n");
}

// Emit a single line to stderr with trailing newline.
export function errorLine(message: string): void {
  impl.err(message + "\n");
}

// ---------------------------------------------------------------------------
// Structured output helpers (always write to stdout)
// ---------------------------------------------------------------------------

export function printJson(data: unknown): void {
  outputLine(JSON.stringify(data, null, 2));
}

export function printTable(rows: Record<string, unknown>[]): void {
  if (rows.length === 0) {
    outputLine("No data");
    return;
  }

  const keys = Object.keys(rows[0]);

  // Convert a cell value to a display string
  const toStr = (v: unknown): string => {
    if (v === null || v === undefined) return "";
    if (typeof v === "object") return JSON.stringify(v);
    return String(v);
  };

  // Calculate max width per column from headers and values
  const widths = keys.map((k) =>
    Math.max(k.length, ...rows.map((r) => toStr(r[k]).length)),
  );

  // Header row
  const header = keys.map((k, i) => k.padEnd(widths[i])).join("  ");
  outputLine(header);

  // Separator line
  const separator = widths.map((w) => "-".repeat(w)).join("  ");
  outputLine(separator);

  // Data rows
  for (const row of rows) {
    const line = keys.map((k, i) => toStr(row[k]).padEnd(widths[i])).join("  ");
    outputLine(line);
  }
}

export function printKv(obj: Record<string, unknown>, indent: number = 0): void {
  const prefix = " ".repeat(indent);
  for (const [key, value] of Object.entries(obj)) {
    if (Array.isArray(value)) {
      impl.out(`${prefix}${key}:\n`);
      for (const item of value) {
        if (item !== null && typeof item === "object" && !Array.isArray(item)) {
          printKv(item as Record<string, unknown>, indent + 2);
        } else {
          impl.out(`${prefix}  ${String(item)}\n`);
        }
      }
    } else if (value !== null && typeof value === "object") {
      impl.out(`${prefix}${key}:\n`);
      printKv(value as Record<string, unknown>, indent + 2);
    } else {
      impl.out(`${prefix}${key}: ${String(value)}\n`);
    }
  }
}
